"use strict";
(function(){
  window.WORKBOOK_EDITORIAL = {
    "OT": {
      "ot-1": {"explanation":"Охрана труда — система предупреждения травм и профессиональных заболеваний, включающая правовые, организационные, технические и санитарные меры. На рабочем месте правила должны быть связаны с конкретными опасностями и локальными инструкциями. Обучающийся обязан понимать, где найти актуальные требования и кому сообщить о небезопасном состоянии.","caseTitle":"Кейс: перед началом занятия нет актуальной инструкции","caseText":"На участке обнаружена инструкция без обозначения редакции, а на рабочем месте изменилось оборудование. Не начинайте операцию по устаревшему документу: сообщите преподавателю/ответственному лицу, запросите действующую инструкцию и уточните порядок допуска.","mistakes":["Считать вводный инструктаж заменой инструктажа на рабочем месте","Работать по устаревшей инструкции","Начинать операцию при неизвестном порядке безопасного выполнения"],"route":["Найти действующие требования","Определить опасности рабочего места","Сверить инструкцию и обучение","Подтвердить готовность к работе"]},
      "ot-2": {"explanation":"Безопасность обеспечивается распределением обязанностей между работодателем, руководителем работ и работником/обучающимся. Работник должен соблюдать инструкции, применять выданные СИЗ, сообщать об опасностях и не выполнять работу без обучения и допуска. Конкретные обязанности и порядок обучения определяются действующими требованиями и локальными документами организации.","caseTitle":"Ситуация: обучающийся не прошёл инструктаж","caseText":"Перед практической работой выяснилось, что обучающийся не ознакомлен с инструкцией по конкретному оборудованию. Практическое задание откладывают до проведения требуемого обучения и проверки понимания правил; нельзя заменять процедуру устным советом одногруппника.","mistakes":["Считать подпись формальностью без понимания правил","Допускать к работе без необходимого обучения","Не сообщать о неисправностях и опасных условиях"],"route":["Определить требуемый вид обучения","Изучить обязанности и ограничения","Пройти инструктаж и проверку знаний","Сообщать об опасностях и соблюдать инструкции"]},
      "ot-3": {"explanation":"Оценка риска начинается с описания операции, опасного фактора, возможного события и последствий. Важно отличать источник опасности от риска и уже наступившего происшествия. Меры выбирают по иерархии: устранение опасности, замена, инженерные и организационные меры, затем СИЗ.","caseTitle":"Кейс: стружка и вращающийся патрон","caseText":"Опишите опасность, опасное событие и возможные последствия при обработке детали. Определите, какие технические меры (ограждение, блокировка), организационные правила и СИЗ предусмотрены. Укажите, при каких неисправностях работу необходимо остановить и сообщить ответственному.","mistakes":["Называть риск просто словом «опасность»","Ставить СИЗ выше устранения опасности и технической защиты","Оценивать риск без описания конкретной операции"],"route":["Описать операцию","Выявить источник опасности","Оценить событие и последствия","Выбрать меры и проверить их действие"]},
      "ot-4": {"explanation":"Производственная санитария и гигиена труда направлены на снижение воздействия шума, вибрации, пыли, аэрозолей, неблагоприятного микроклимата и других факторов. Оценивать условия следует по результатам установленного контроля и нормативам; личные ощущения не заменяют измерения и документацию.","caseTitle":"Кейс: повышенный шум и аэрозоль СОЖ","caseText":"На рабочем месте отмечены шум и аэрозоль охлаждающей жидкости. Зафиксируйте источник и условия воздействия, проверьте исправность местной вытяжки и ограждений, изучите предусмотренные меры защиты и сообщите о признаках неисправности. Не назначайте допустимые уровни самостоятельно.","mistakes":["Считать кратковременное воздействие безвредным без оценки","Игнорировать вентиляцию и состояние оборудования","Подменять измерения субъективной оценкой"],"route":["Выявить санитарный фактор","Проверить технические меры","Сверить результаты контроля с требованиями","Применить предусмотренную защиту"]},
      "ot-5": {"explanation":"Электробезопасность требует исключить контакт с токоведущими частями и использовать только исправное оборудование. Перед работой обращают внимание на целостность кабелей, вилок, корпусов, защитного заземления и доступность аварийного отключения. Электроремонт и вскрытие оборудования выполняют только уполномоченные специалисты по установленной процедуре.","caseTitle":"Ситуация: повреждён кабель станка","caseText":"При осмотре обнаружена повреждённая изоляция кабеля или следы нагрева разъёма. Не касайтесь повреждённого участка и не пытайтесь перемотать его самостоятельно. Прекратите использование оборудования безопасным способом, ограничьте доступ и сообщите ответственному лицу.","mistakes":["Использовать удлинитель с повреждённой изоляцией","Самостоятельно вскрывать электрооборудование без допуска","Игнорировать запах гари, нагрев и срабатывание защиты"],"route":["Осмотреть кабель и корпус без вскрытия","Не использовать повреждённое оборудование","Отключение выполняет уполномоченное лицо","Сообщить и дождаться разрешения на работу"]},
      "ot-6": {"explanation":"Пожарная безопасность включает предупреждение возгорания, знание путей эвакуации и правильные действия при обнаружении дыма или огня. Приоритет — оповещение, вызов экстренных служб и безопасная эвакуация. Тушить начальный очаг можно только если это не угрожает жизни, есть подготовка и путь отхода остаётся свободным.","caseTitle":"Ситуация: дым в учебной мастерской","caseText":"Обнаружив дым, предупредите окружающих, сообщите по установленному порядку и вызовите 112. Покиньте помещение по обозначенному маршруту, не пользуйтесь лифтом и не возвращайтесь за вещами. Не пытайтесь тушить пожар, если есть угроза, сильное задымление или отсутствует безопасный выход.","mistakes":["Прятаться или пытаться самостоятельно выяснить источник дыма","Блокировать эвакуационный выход материалами","Возвращаться в помещение после эвакуации без разрешения"],"route":["Обнаружить и сообщить","Подать сигнал и вызвать 112","Эвакуироваться по плану","Собраться в безопасной зоне и доложить"]},
      "ot-7": {"explanation":"Средства коллективной защиты уменьшают воздействие опасности на всех находящихся в зоне работ: ограждения, блокировки, вентиляция, экраны и сигнализация. СИЗ применяют как дополнительный барьер по результатам оценки риска и требованиям инструкции. Выбор, исправность и совместимость средств должны соответствовать конкретной операции.","caseTitle":"Кейс: очки есть, но ограждение снято","caseText":"Перед обработкой оператор обнаружил снятое ограждение, хотя защитные очки и обувь на месте. Не начинайте работу: СИЗ не заменяют штатное ограждение и блокировку. Сообщите о неисправности и дождитесь восстановления коллективной защиты и разрешения на запуск.","mistakes":["Считать СИЗ заменой ограждению и блокировке","Использовать повреждённые или неподходящие СИЗ","Не проверять совместимость защиты с операцией"],"route":["Определить опасность","Проверить коллективную защиту","Подобрать предусмотренные СИЗ","Проверить состояние перед работой"]},
      "ot-8": {"explanation":"При работе на металлорежущем оборудовании опасны вращающиеся детали, патрон, режущий инструмент, стружка, перемещения осей и неожиданный запуск. Ограждения и блокировки должны быть исправны; измерение, очистка и наладка выполняются только в безопасном состоянии по инструкции конкретного станка.","caseTitle":"Ситуация: стружка намоталась на деталь","caseText":"Не пытайтесь снять стружку рукой или ветошью. Остановите процесс штатным способом, дождитесь полной остановки и действуйте только подходящим инструментом по инструкции. Если причина связана с режимом, инструментом или неисправностью — сообщите ответственному специалисту.","mistakes":["Работать в перчатках рядом с вращающимися частями","Оставлять ключ в патроне","Обходить блокировку или очищать станок на ходу"],"route":["Проверить ограждения и блокировки","Закрепить заготовку и инструмент","Выполнить безопасный запуск","Остановить станок перед измерением и очисткой"]},
      "ot-9": {"explanation":"Слесарно-сборочные, сварочные и монтажные работы связаны с риском порезов, защемления, падения деталей, искр, горячего металла и опасных газов. До начала работ проверяют устойчивость изделия, исправность инструмента и оснастки, защитные экраны и организацию рабочей зоны. Для сварки дополнительно соблюдают требования к вентиляции, экранированию и допуску.","caseTitle":"Кейс: сборка тяжёлого узла и сварка рядом","caseText":"Перед перемещением узла оцените массу, устойчивость и способ строповки; не стойте под поднятым грузом и не помещайте руки между сопрягаемыми деталями. Если рядом выполняется сварка, согласуйте разделение зон, экраны и вентиляцию по инструкции мастерской.","mistakes":["Подставлять руки между деталями при совмещении отверстий","Использовать неисправный подъёмный или слесарный инструмент","Выполнять сварку без предусмотренного ограждения и вентиляции"],"route":["Подготовить и оградить рабочую зону","Проверить инструмент и оснастку","Безопасно переместить и закрепить узел","Выполнить операцию и проверить результат"]},
      "ot-10": {"explanation":"Термические, химические и композитные процессы могут сопровождаться высокой температурой, горячими поверхностями, парами, пылью, реактивами и продуктами разложения. Конкретные меры определяются технологической картой, паспортами безопасности веществ и инструкцией оборудования. Нельзя смешивать материалы или изменять режимы без утверждённой процедуры.","caseTitle":"Ситуация: неизвестная ёмкость рядом с участком обработки","caseText":"Не открывайте и не перемещайте ёмкость без маркировки. Ограничьте доступ, сообщите ответственному лицу и запросите сведения о содержимом и паспорте безопасности. При термической обработке не касайтесь горячих деталей без предусмотренной защиты и инструмента.","mistakes":["Работать с веществом без маркировки и паспорта безопасности","Снимать горячую деталь неподходящим инструментом","Изменять технологический режим без разрешения"],"route":["Идентифицировать материал и процесс","Изучить инструкцию и паспорт безопасности","Проверить вентиляцию и защиту","Выполнить операцию по утверждённой процедуре"]},
      "ot-11": {"explanation":"При несчастном случае сначала оценивают безопасность места происшествия, чтобы не допустить второго пострадавшего. Затем вызывают 112 или 103 по ситуации и действуют в пределах подготовки: следуют указаниям диспетчера, оказывают доступную помощь и не выполняют опасных манипуляций. При электротравме нельзя касаться пострадавшего до безопасного прекращения воздействия тока.","caseTitle":"Ситуация: пострадавший рядом с электрооборудованием","caseText":"Не приближайтесь к пострадавшему, пока место остаётся под напряжением. Организуйте безопасное отключение силами уполномоченного лица, вызовите 112/103 и следуйте инструкциям диспетчера. После устранения опасности оцените состояние и оказывайте помощь только в пределах освоенных навыков.","mistakes":["Касаться пострадавшего до устранения электрической опасности","Перемещать человека без необходимости и подготовки","Задерживать вызов экстренной помощи"],"route":["Убедиться в безопасности места","Вызвать 112/103","Следовать указаниям диспетчера","Оказывать помощь в пределах подготовки"]},
      "ot-12": {"explanation":"Расследование несчастных случаев направлено на установление обстоятельств и причин, а не на сокрытие происшествия или поиск виновного по предположению. Важно своевременно сообщить о событии, сохранить доступные сведения и документы, зафиксировать условия и содействовать установленной процедуре. Выводы должны опираться на факты.","caseTitle":"Кейс: почти произошёл несчастный случай","caseText":"Заготовка сорвалась с крепления, но травмы не было. Зафиксируйте событие и условия, сообщите ответственному лицу, не возобновляйте работу до проверки закрепления и оборудования. Предложите профилактические меры и укажите, какие данные помогут выяснить первопричину.","mistakes":["Скрывать происшествие, если нет травмы","Менять место события до фиксации без необходимости спасения","Обвинять работника без анализа оборудования и организации процесса"],"route":["Остановить опасную работу","Сообщить и зафиксировать факты","Установить причины по материалам проверки","Выполнить профилактические меры и проверить их"]}
    },
    "MCAM": {
      "mc-t11": {"explanation":"Рабочее пространство Mastercam объединяет геометрию, заготовку, систему координат, инструменты и группы операций. Перед созданием траектории проверьте, какой файл и версия проекта открыты, где расположены менеджеры геометрии и операций и какие элементы относятся к текущей детали. Команды и панели могут отличаться между версиями, поэтому ориентируйтесь на руководство установленной версии.","caseTitle":"Практикум: подготовить рабочее пространство проекта","caseText":"Откройте учебный проект и найдите дерево геометрии, группы операций, библиотеку инструментов и область визуализации. Составьте схему взаимосвязей объектов и сохраните отдельную рабочую копию. До изменений проверьте единицы, ориентацию модели и имя проекта.","mistakes":["Начинать программирование в неверном или устаревшем файле","Путать дерево геометрии и список операций","Не сохранять исходную копию проекта"],"route":["Проверить файл и версию","Найти основные менеджеры","Проверить единицы и ориентацию","Сохранить учебную копию"]},
      "mc-t12": {"explanation":"Визуализация и анализ геометрии помогают проверить модель до назначения обработки. Важно отличать поворот вида от изменения геометрии, проверять видимость и выбранные уровни, оценивать размеры и целостность поверхностей. Измеренные значения сравнивают с чертежом, а не используют как замену конструкторским требованиям.","caseTitle":"Кейс: модель выглядит правильно, но размеры не совпадают","caseText":"Откройте модель, выполните осмотр с нескольких направлений, проверьте габариты и ключевые элементы геометрии. Сопоставьте измерения с чертежом, зафиксируйте расхождения и не переходите к траекториям, пока не подтверждены единицы и геометрия.","mistakes":["Принимать удобный ракурс за подтверждение геометрии","Не проверять масштаб и единицы модели","Игнорировать разрывы и дублирующиеся поверхности"],"route":["Выбрать виды и осмотреть модель","Проверить габариты и единицы","Исследовать проблемные элементы","Сверить геометрию с чертежом"]},
      "mc-t13": {"explanation":"Файловые команды управляют сохранением и передачей проекта. При архивировании важно учитывать не только основной файл, но и связанные модели, библиотеки и внешние зависимости. Zip2Go и аналогичные средства подготовки пакета используют для передачи проекта; после упаковки нужно проверить состав и возможность открыть копию на другом рабочем месте.","caseTitle":"Кейс: передать проект на другой компьютер","caseText":"Подготовьте копию учебного проекта, проверьте связанные файлы и зависимости, сформируйте пакет передачи доступным в вашей версии способом. Откройте распакованную копию и убедитесь, что геометрия, операции и инструменты доступны. Оригинал оставьте неизменным.","mistakes":["Передавать только главный файл при наличии внешних ссылок","Не проверять архив после создания","Перезаписывать исходный проект вместо копии"],"route":["Сохранить отдельную копию","Проверить связанные файлы","Сформировать пакет проекта","Открыть пакет и проверить комплектность"]},
      "mc-t21": {"explanation":"Levels помогают организовать геометрию по назначению и управлять её видимостью и выбором. Разделяйте исходную модель, вспомогательную геометрию, границы обработки и элементы оснастки. Соглашение об именах уровней облегчает проверку проекта и снижает риск случайного выбора лишней геометрии.","caseTitle":"Практикум: организовать уровни учебной детали","caseText":"Создайте понятную структуру уровней для исходной модели, вспомогательных построений, границ обработки и элементов закрепления. Проверьте, какие уровни видимы и доступны для выбора на каждом этапе. Сохраните проект и объясните, как структура помогает избежать ошибок.","mistakes":["Хранить все элементы на одном уровне без различения","Случайно скрыть геометрию, нужную для операции","Удалять исходные элементы вместо управления видимостью"],"route":["Разделить геометрию по назначению","Назвать уровни понятно","Проверить видимость и выбор","Сохранить структуру проекта"]},
      "mc-t22": {"explanation":"WCS задаёт рабочую систему координат, Cplane — плоскость построения, Tplane — плоскость инструмента. Их взаимное положение определяет ориентацию программирования и подхода инструмента. Перед созданием траектории проверьте начало координат, направление осей и соответствие установки детали выбранной системе.","caseTitle":"Кейс: траектория построена в неверной ориентации","caseText":"На учебной модели определите базовую плоскость детали и требуемую ориентацию операции. Сравните WCS, Cplane и Tplane, проверьте начало координат и направление осей. Зафиксируйте, какие настройки относятся к построению геометрии, а какие — к ориентации инструмента.","mistakes":["Считать WCS, Cplane и Tplane одним параметром","Не сверять направление осей с установкой детали","Менять ноль после построения траекторий без повторной проверки"],"route":["Определить базу и установку","Настроить рабочую систему координат","Выбрать плоскости построения и инструмента","Проверить ориентацию и ноль"]},
      "mc-t23": {"explanation":"Chaining задаёт последовательность геометрических элементов, которые Mastercam использует как границу или направляющую траектории. Важны направление цепочки, точка старта, связность элементов и корректная обработка разрывов. Перед подтверждением выбора проверьте, что цепочка описывает нужную сторону и не захватывает лишнюю геометрию.","caseTitle":"Практикум: выбрать замкнутый контур кармана","caseText":"На учебной геометрии выберите границу кармана как цепочку. Проверьте направление обхода, начальную точку, замкнутость и отсутствие посторонних сегментов. Сравните выбранную цепочку с чертежом и сохраните скриншот или запись результата только из установленной программы.","mistakes":["Выбирать соседний контур вместо нужной границы","Не проверять направление и стартовую точку","Оставлять разрыв или лишний сегмент"],"route":["Выделить нужную геометрию","Собрать цепочку","Проверить направление и замкнутость","Подтвердить соответствие чертежу"]},
      "mc-t31": {"explanation":"Tool Manager хранит определения режущих инструментов и их геометрию. Для корректной симуляции и постпроцессирования важны тип инструмента, диаметр, рабочая длина, число зубьев, державка и связанные параметры. Значения выбирают по реальному инструменту и документации, а не по внешнему сходству модели.","caseTitle":"Кейс: в симуляции инструмент не соответствует установленному","caseText":"Выберите инструмент из учебной библиотеки и сравните его определение с паспортом или заданием: тип, диаметр, рабочую длину, число зубьев и держатель. Проверьте номер инструмента и корректоры, затем сохраните ссылку на используемое определение.","mistakes":["Выбирать инструмент только по диаметру","Не учитывать держатель и рабочую длину","Путать номер инструмента с номером корректора"],"route":["Определить тип операции","Выбрать подходящий инструмент","Сверить геометрию и держатель","Проверить номер и связь с операцией"]},
      "mc-t32": {"explanation":"Stock Setup описывает исходную заготовку, относительно которой рассчитывается снятие материала. Её форма, габариты, ориентация и положение относительно нуля должны соответствовать заданию. Ошибка в заготовке искажает симуляцию, оценку остатка и безопасных перемещений.","caseTitle":"Кейс: симуляция показывает лишний или отсутствующий материал","caseText":"Сверьте форму и габариты заготовки с чертежом или учебным заданием, проверьте ориентацию и положение относительно рабочего нуля. Сравните модель заготовки с деталью и убедитесь, что припуск задан обоснованно. Не назначайте реальные размеры по иллюстративному примеру.","mistakes":["Использовать габариты модели детали как заготовку без припуска","Задать неверную ориентацию или ноль","Не проверять заготовку перед симуляцией"],"route":["Получить исходные данные заготовки","Задать форму и габариты","Связать заготовку с системой координат","Проверить положение относительно модели"]},
      "mc-t41": {"explanation":"Contour обрабатывает выбранную цепочку по заданной стратегии. Нужно определить сторону обработки, глубины, проходы, припуски, подход и отход, а также учесть геометрию инструмента и держателя. Сама линия траектории не подтверждает качество результата: важны симуляция и контроль остаточного материала.","caseTitle":"Кейс: контурная обработка наружного профиля","caseText":"Выберите профиль из учебной модели, определите сторону обработки и глубину по заданию. Настройте инструмент, припуск, число проходов и безопасные подходы. Проверьте траекторию в симуляции и сравните полученную форму с чертежом.","mistakes":["Обрабатывать не ту сторону цепочки","Не учитывать радиус инструмента и припуск","Не проверять вход/выход и столкновения"],"route":["Выбрать цепочку и сторону","Назначить инструмент и глубины","Настроить проходы и подходы","Симулировать и проверить результат"]},
      "mc-t42": {"explanation":"Pocket предназначена для удаления материала внутри заданной границы с учётом островков и ограничений геометрии. Выбор стратегии зависит от формы кармана, инструмента, глубины и требуемого качества. Перед расчётом проверьте замкнутость границ, островки, врезание, шаг по глубине и остаточный припуск.","caseTitle":"Кейс: карман с островком","caseText":"На учебной модели выберите внешний контур кармана и внутренний островок. Укажите глубину и инструмент по условию задания, выберите допустимую стратегию и способ врезания. Просмотрите траекторию, проверьте, что островок не удаляется и держатель не сталкивается с моделью.","mistakes":["Не распознать внутренний островок","Назначить глубину без проверки задания","Игнорировать врезание и остаточный материал"],"route":["Выбрать внешнюю границу и островки","Задать глубину и инструмент","Настроить стратегию и врезание","Проверить траекторию и остаток"]},
      "mc-t51": {"explanation":"Симуляция проверяет рассчитанную траекторию относительно модели детали, заготовки и элементов станочной системы. Перед выпуском УП анализируют столкновения, остаточный материал, смены инструмента и безопасные перемещения. Постпроцессор должен соответствовать конкретной стойке и конфигурации станка; полученный NC-файл требует отдельной проверки.","caseTitle":"Кейс: подготовить NC-файл к передаче на проверку","caseText":"Запустите симуляцию проекта, просмотрите все операции и смены инструмента, проверьте столкновения и остаточный материал. Выберите только подтверждённый постпроцессор для целевой стойки, сформируйте файл и проверьте его структуру по правилам предприятия. Не запускайте учебный NC-файл на станке.","mistakes":["Считать отсутствие столкновений в CAM полной гарантией безопасности","Использовать постпроцессор для другой стойки","Передавать NC-файл без просмотра и проверки на целевом оборудовании"],"route":["Проверить все операции в симуляции","Устранить столкновения и остатки","Выбрать подтверждённый постпроцессор","Проверить NC-файл и документацию"]}
    },
    "SPRUT_TP": {
      "Тема 1.1": {"explanation":"СПРУТ-ТП — инструмент автоматизации технологической подготовки производства. Он хранит структуру изделия и технологического процесса, связывает операции с ресурсами и помогает выпускать документы. Инженерная ответственность остаётся у технолога: программа не проверяет за него полноту чертежа, корректность баз и применимость выбранной технологии.","caseTitle":"Кейс: первый проект в СПРУТ-ТП","caseText":"Получено задание на технологический процесс для детали. До ввода данных зафиксируйте версию программы, проверьте обозначение и редакцию чертежа, материал и требования к детали. Создайте учебную копию проекта, определите структуру изделия и отметьте исходные данные, которых не хватает.","mistakes":["Считать автоматически сформированный документ готовым без проверки","Работать в оригинале демонстрационного проекта","Подменять отсутствующие исходные данные догадками"],"route":["Проверить исходные документы","Создать копию проекта","Определить структуру изделия и ТП","Проверить результат и комплект документов"]},
      "Тема 1.2": {"explanation":"Технологические процессы классифицируют по двум независимым признакам. Единичный, типовой и групповой характеризуют область применения процесса; маршрутный, операционный и маршрутно-операционный — глубину описания работ. Эти признаки нельзя смешивать: например, единичный процесс может быть представлен маршрутной или более подробной документацией.","caseTitle":"Кейс: выбрать вид ТП и степень детализации","caseText":"Сравните три задания: изготовить уникальную ремонтную втулку; организовать выпуск семейства сходных втулок; обработать несколько разных корпусов с общей технологической основой. Для каждого обоснуйте единичный, типовой или групповой процесс, а затем отдельно выберите уровень детализации документов.","mistakes":["Считать типовой и маршрутный одной классификацией","Называть групповой процессом для полностью одинаковых деталей","Выбирать детализацию без учёта требований производства"],"route":["Определить область применения","Сопоставить конструктивные и технологические признаки","Выбрать единичный, типовой или групповой ТП","Отдельно выбрать степень детализации"]},
      "Тема 1.3": {"explanation":"Комплект технологических документов распределяет информацию по назначению. Маршрутная карта показывает ход процесса и операции; операционная раскрывает выполнение конкретной операции; карта эскизов поясняет установку, базы и обрабатываемые поверхности. Документы должны быть согласованы по обозначениям, номерам операций, материалу и контрольным требованиям.","caseTitle":"Кейс: обнаружено расхождение между МК и ОК","caseText":"В маршрутной карте указана токарная операция, а в операционной карте — другая установка и инструмент. Сверьте редакции документов, номера и содержание операции, чертёж и принятую технологию. Зафиксируйте расхождение и передайте на корректировку до выпуска комплекта.","mistakes":["Дублировать всю информацию во всех документах без структуры","Не сверять номера операций и обозначения","Считать карту эскизов заменой чертежа"],"route":["Определить назначение каждого документа","Распределить сведения по формам","Сверить обозначения и операции","Провести нормоконтроль комплекта"]},
      "Тема 2.1": {"explanation":"Рабочая среда СПРУТ-ТП организует проект, технологические документы и нормативно-справочную информацию. В проекте следует различать изделие, технологический процесс, операции, переходы, ресурсы и связанные файлы. Названия панелей и расположение команд зависят от версии и конфигурации, поэтому практическое задание выполняют по установленной версии и её руководству.","caseTitle":"Практикум: ориентирование в проекте и справочниках","caseText":"Откройте учебную копию проекта. Найдите карточку изделия, список ТП, операции, переходы, справочники оборудования и инструмента, а также связанные чертежи. Составьте таблицу: объект, назначение, где найден, какие поля нельзя менять без основания.","mistakes":["Редактировать справочник вместо записи конкретного проекта","Не проверять версию и конфигурацию программы","Удалять связи с исходными файлами"],"route":["Открыть учебную копию","Найти структуру проекта","Просмотреть справочники и связанные файлы","Зафиксировать версию и результаты осмотра"]},
      "Тема 2.2": {"explanation":"Исходные данные определяют допустимые технологические решения. К ним относятся чертёж и спецификация, материал и состояние поставки, требования точности и поверхности, термообработка и покрытия, объём выпуска, доступное оборудование и правила предприятия. Каждый параметр должен иметь источник и актуальную редакцию.","caseTitle":"Кейс: исходных данных недостаточно","caseText":"В чертеже корпуса указан материал, но отсутствуют сведения о покрытии, а в спецификации есть ссылка на другую редакцию. Составьте перечень противоречий, отметьте источник каждого известного параметра и подготовьте запрос на уточнение. Не назначайте заготовку и операции по неподтверждённым сведениям.","mistakes":["Использовать устаревшую редакцию чертежа","Принимать справочное значение за требование конструкторской документации","Не фиксировать пробелы и противоречия"],"route":["Проверить комплектность документов","Извлечь требования к детали","Сверить материал и производственную программу","Зафиксировать вопросы и получить подтверждение"]},
      "Тема 3.1": {"explanation":"Маршрутный технологический процесс задаёт последовательность операций и общую логику изготовления детали. При его разработке анализируют чертёж, выбирают заготовку и технологические базы, группируют переходы в операции, определяют типы оборудования и контрольные этапы. Конкретные режимы и допуски берут из подтверждённых исходных данных и документации.","caseTitle":"Кейс: маршрут обработки ступенчатого вала","caseText":"По учебному чертежу составьте перечень этапов: получение и подготовка заготовки, обработка баз, черновое и чистовое точение, дополнительные операции по чертежу и контроль. Для каждого этапа укажите цель, оборудование-кандидат, базу и результат контроля; обоснуйте порядок.","mistakes":["Назначать операции без анализа баз и припусков","Ставить чистовую обработку до операций, способных повредить поверхность","Не включать контроль критических размеров"],"route":["Изучить чертёж и материал","Выбрать заготовку и базы","Составить последовательность операций","Проверить маршрут на полноту и логичность"]},
      "Тема 3.2": {"explanation":"Операционный технологический процесс раскрывает конкретную операцию: установы, переходы, оборудование, приспособления, инструмент, последовательность действий и контроль. Детализация должна позволять исполнителю однозначно понять, что делать и как подтвердить результат, не додумывая отсутствующие параметры.","caseTitle":"Кейс: раскрыть токарную операцию","caseText":"Возьмите одну токарную операцию из маршрутного процесса. Разделите её на установы и переходы, укажите базирование, закрепление, инструмент, обрабатываемые поверхности и контроль. Все режимы и допуски привяжите к заданию или нормативному источнику; недостающие данные пометьте для согласования.","mistakes":["Оставлять переходы на уровне общих фраз","Не указывать базирование и контроль","Переносить режимы из похожей детали без проверки"],"route":["Выбрать операцию маршрута","Определить установы и переходы","Назначить подтверждённые ресурсы","Описать контроль и проверить согласованность"]},
      "Тема 3.3": {"explanation":"Маршрутно-операционный процесс объединяет обзор всего маршрута с подробным описанием тех операций, где это необходимо. Такой подход сохраняет общую последовательность изготовления и одновременно раскрывает критические установки, переходы, инструмент и контроль. Уровень детализации выбирают по сложности и требованиям производства.","caseTitle":"Кейс: где нужна подробная операционная карта","caseText":"Для детали составьте полный маршрут, затем выберите операции с повышенным риском ошибки или сложным базированием для подробной проработки. Объясните, почему одних сведений маршрутной карты достаточно для одних этапов, но недостаточно для других.","mistakes":["Дублировать подробное описание без необходимости","Оставлять критическую операцию без переходов и контроля","Терять связь между номером операции и подробной картой"],"route":["Составить полный маршрут","Выделить критические операции","Детализировать установки и переходы","Сверить номера и документы"]},
      "Тема 4.1": {"explanation":"Типовой технологический процесс применяют к группе изделий с общими конструктивными и технологическими признаками; групповой — к деталям, которые могут различаться, но имеют общую технологическую основу и требуют групповой оснастки или организации обработки. Область применимости должна быть определена явно, а отличия конкретной детали — отражены в варианте процесса.","caseTitle":"Кейс: можно ли применить типовой или групповой процесс","caseText":"Сравните три детали по материалу, форме, базам, точности и основным операциям. Определите, достаточно ли общего конструктивно-технологического сходства для типового процесса или разумнее группировать детали по общности операций. Укажите признаки, которые потребуют индивидуальной корректировки.","mistakes":["Объединять детали только по внешнему сходству","Копировать маршрут без проверки баз и допусков","Не фиксировать границы применимости процесса"],"route":["Сравнить конструкцию и требования","Найти общие операции и базы","Определить область применимости","Описать отличия и варианты"]},
      "Тема 4.2": {"explanation":"Аналог и шаблон ускоряют проектирование, но не являются готовым решением для новой детали. Перед использованием сравнивают материал, геометрию, точность, базирование, тип производства, оборудование и контроль. Переносимые сведения подтверждают; неприменимые параметры удаляют или корректируют с документированным основанием.","caseTitle":"Кейс: аналог найден, но деталь отличается","caseText":"Выберите похожий процесс и составьте таблицу сходств и различий новой детали с аналогом. Отдельно отметьте, что можно перенести, что нужно пересчитать или согласовать, а что нельзя использовать. Проверьте, не осталось ли в копии чужих обозначений, материалов и контрольных требований.","mistakes":["Копировать аналог целиком","Не проверять актуальность исходного процесса","Оставлять в документе обозначения другой детали"],"route":["Найти кандидата-аналога","Сравнить ключевые признаки","Отметить переносимые и непереносимые данные","Проверить адаптированный процесс"]},
      "Тема 5.1": {"explanation":"Технологический процесс механической обработки превращает заготовку в деталь с заданными размерами, формой и качеством поверхности. Маршрут зависит от материала, припусков, жёсткости, базирования и требований чертежа. Черновые, получистовые и чистовые этапы распределяют так, чтобы обеспечить точность и не повредить уже обработанные поверхности.","caseTitle":"Кейс: маршрут механической обработки корпуса","caseText":"По чертежу корпуса определите основные поверхности, базы и отверстия. Предложите последовательность получения баз, черновой обработки, обработки отверстий и чистовых переходов. Для каждого этапа укажите, какие поверхности формируются и чем будет подтверждён результат.","mistakes":["Не учитывать изменение жёсткости после снятия материала","Нарушать последовательность базирования","Не планировать контроль межоперационных размеров"],"route":["Анализировать поверхности и допуски","Выбрать базы и заготовку","Составить последовательность обработки","Определить межоперационный и итоговый контроль"]},
      "Тема 5.2": {"explanation":"Заготовительные и специальные операции подготавливают материал и заготовку либо придают детали свойства, которые нельзя получить только механическим резанием. К ним могут относиться резка, литьё, штамповка, сварка, термическая и химико-термическая обработка, покрытия. Включать операцию следует только при наличии требования и подходящей технологии.","caseTitle":"Кейс: выбрать подготовительные и специальные операции","caseText":"Для условной стальной детали с требованием к твёрдости и покрытию определите, какие операции могут потребоваться до и после механической обработки. Укажите, какие исходные требования нужно уточнить, какие деформации или припуски учитывать и где разместить контроль.","mistakes":["Назначать термообработку без требования чертежа или технологии","Не учитывать деформации и припуски после специальной операции","Считать все виды покрытий взаимозаменяемыми"],"route":["Выделить требования к материалу и поверхности","Выбрать допустимую операцию по документации","Определить место в маршруте","Предусмотреть контроль результата"]},
      "Тема 6.1": {"explanation":"Нормирование технологического процесса определяет обоснованные затраты времени на выполнение операций. В расчёте различают подготовительно-заключительное время и штучное время; состав штучного времени зависит от операции и принятой методики. Нормативы применяют с учётом оборудования, организации рабочего места и утверждённых документов предприятия.","caseTitle":"Кейс: проверить состав нормы времени","caseText":"Для учебной операции составьте перечень составляющих времени: основное, вспомогательное, обслуживание рабочего места, отдых и личные надобности — в соответствии с принятой на занятии методикой. Отдельно укажите подготовительно-заключительное время и условия, от которых зависит его распределение на партию. Не подставляйте вымышленные нормативные значения.","mistakes":["Смешивать штучное и подготовительно-заключительное время","Использовать норматив без проверки применимости","Принимать учебный расчёт за утверждённую норму предприятия"],"route":["Определить операцию и условия","Выбрать применимую методику","Разложить время на составляющие","Проверить источник нормативов и расчёт"]},
      "Тема 6.2": {"explanation":"Нормоконтроль и выпуск технологической документации проверяют полноту, единообразие, взаимную согласованность и соответствие принятым правилам оформления. До выпуска сверяют обозначения, номера операций, материал, оборудование, оснастку, инструмент, режимы и контрольные требования, а также редакции связанных документов.","caseTitle":"Кейс: подготовить комплект ТД к выпуску","caseText":"Проведите проверку учебного комплекта: сравните маршрутную и операционные карты, чертёж, спецификацию и карту эскизов. Найдите несогласованные номера, отсутствующие ссылки, неоднозначные единицы и устаревшие обозначения. Составьте перечень замечаний и критерии повторной проверки после исправления.","mistakes":["Проверять оформление без проверки технического содержания","Не сверять комплект документов между собой","Выпускать документ с незакрытыми замечаниями"],"route":["Проверить комплектность и редакции","Сверить содержание и обозначения","Оформить замечания","Повторно проверить и выпустить комплект"]}
    },
    "07.01": {
      "t-1-1": {explanation:"Работа оператора — это управляемый цикл: подготовить место и станок, проверить задание, установить заготовку, безопасно проверить УП, вести обработку и контролировать деталь. Оператор не заменяет технолога и не вносит самовольные изменения в утверждённую программу.", caseTitle:"Ситуация: первая деталь после наладки", caseText:"После пробного прохода оператор обнаружил размер больше допуска. Правильный порядок: остановить цикл безопасным способом, отделить деталь, проверить измерение, ноль, корректор инструмента и запись режима; сообщить наладчику. Нельзя незаметно менять программу и продолжать партию.", mistakes:["Начинать работу без чтения задания и чертежа","Измерять деталь при движении шпинделя","Считать первую годную деталь гарантией стабильности всей партии"], route:["Задание и чертёж","Осмотр станка и оснастки","Проверка УП и пробный прогон","Обработка и контроль"]},
      "t-1-2": {explanation:"Тип станка выбирают не по принципу «самый современный», а по детали и производственной задаче. Важны форма, материал, габариты, точность, партия, доступный инструмент и возможности оборудования. Универсальный станок гибок, ЧПУ обеспечивает повторяемость при грамотной подготовке.",caseTitle:"Кейс: вал для единичного заказа и партия втулок",caseText:"Для единичной простой детали может быть рационален универсальный станок. Для повторяющейся партии со сложным профилем часто выгоднее ЧПУ. Решение обоснуйте точностью, временем переналадки, объёмом партии и стоимостью подготовки.",mistakes:["Сравнивать станки только по мощности","Игнорировать максимальные габариты и ход осей","Забывать про оснастку, инструмент и квалификацию"],route:["Чертёж и материал","Объём выпуска","Точность и габариты","Выбор типа станка"]},
      "t-1-3": {explanation:"Станок — система взаимосвязанных узлов. Станина задаёт базу и направляющие; передняя бабка и шпиндель обеспечивают вращение; суппорт перемещает резец; задняя бабка поддерживает длинную деталь и удерживает осевой инструмент.",caseTitle:"Кейс: появляется конусность на длинном валу",caseText:"Проверьте не только резец: возможны смещение задней бабки, прогиб заготовки, недостаточная жёсткость закрепления, износ направляющих или неправильная поддержка люнетом. Диагностику выполняют по инструкции и с остановленным оборудованием.",mistakes:["Путать назначение шпинделя и суппорта","Не учитывать вылет заготовки","Считать заднюю бабку только держателем сверла"],route:["Станина и направляющие","Шпиндель и патрон","Суппорт и резцедержатель","Задняя бабка и оснастка"]},
      "t-1-4": {explanation:"Безопасность — часть технологического процесса, а не формальность. Опасность создают вращающиеся детали, патрон, стружка, инструмент, СОЖ, электрические и механические неисправности. Любое измерение, очистка и регулировка выполняются только в безопасном состоянии по инструкции.",caseTitle:"Ситуация: стружка намоталась на деталь",caseText:"Не пытайтесь снять её рукой или ветошью. Остановите станок штатным способом, дождитесь полной остановки, действуйте подходящим крючком или щёткой согласно инструкции и сообщите о неисправности, если требуется.",mistakes:["Оставлять ключ в патроне","Работать в перчатках рядом с вращением","Открывать ограждение и обходить блокировки"],route:["Выявить опасность","Остановить процесс безопасно","Устранить причину по инструкции","Проверить защиту перед пуском"]},
      "t-2-1": {explanation:"Технологический процесс обработки вала связывает чертёж с реальными операциями. Нужно определить базы, припуски, последовательность переходов, инструмент, режимы и контроль. Черновая обработка снимает основной припуск, чистовая формирует требуемую точность и поверхность.",caseTitle:"Производственная задача: вал ступенчатый",caseText:"Сначала изучите размеры и допуски, выберите базирование и способ закрепления. Затем назначьте подрезку торца, черновое и чистовое точение, обработку канавок/резьбы при наличии, контроль диаметров и длины. Последовательность обоснуйте жёсткостью и точностью.",mistakes:["Назначать переходы без чтения чертежа","Не оставлять припуск под чистовую обработку","Контролировать только общий диаметр, забывая длины и уступы"],route:["Анализ чертежа","Базирование и закрепление","Переходы и режимы","Контроль размеров"]},
      "t-2-2": {explanation:"Резьба задаётся номинальным диаметром, шагом, профилем и направлением. Наружную резьбу получают резьбовым резцом или плашкой, внутреннюю — метчиком либо расточным резьбовым инструментом. Диаметр отверстия под внутреннюю резьбу выбирают по таблицам и стандарту.",caseTitle:"Кейс: наружная резьба М20×2",caseText:"До обработки уточните длину резьбы, направление, выход резца и требуемый класс точности. Проверьте заготовку, профиль инструмента, синхронизацию подачи с шагом и предусмотрите контроль калибром или резьбомером.",mistakes:["Путать диаметр и шаг","Не проверять направление резьбы","Контролировать резьбу только линейкой или на глаз"],route:["Определить обозначение","Подготовить диаметр и фаску","Выбрать инструмент и цикл","Проверить калибром"]},
      "t-2-3": {explanation:"Коническая поверхность характеризуется большим и малым диаметрами, длиной и углом конуса. Способ получения выбирают по величине конуса, длине, точности и возможностям станка: поворот верхних салазок, смещение задней бабки, копирное устройство или программная траектория.",caseTitle:"Кейс: конусная посадочная поверхность",caseText:"По чертежу определите диаметры и длину конуса, рассчитайте угол или конусность, выберите способ обработки. После пробного прохода проверьте размеры в нескольких сечениях и прилегание по установленной методике.",mistakes:["Путать угол конуса и конусность","Не учитывать длину конуса","Проверять только один диаметр"],route:["Считать параметры конуса","Выбрать способ обработки","Настроить перемещение","Проверить профиль"]},
      "t-3-1": {explanation:"Подготовка УП начинается до написания кадров. Технолог анализирует чертёж, выбирает базирование, операции, инструмент, режимы, систему координат и стратегию обработки. Затем создаёт траекторию, проверяет столкновения и постпроцессирует программу под конкретную стойку.",caseTitle:"Кейс: программа для новой детали",caseText:"Сверьте модель и чертёж, назначьте заготовку, ноль, инструмент и безопасные плоскости. Проверьте симуляцию, переходы между инструментами, ограничения станка и соответствие постпроцессора. Перед реальным запуском нужна установленная процедура пробного прогона.",mistakes:["Писать код без технологического плана","Не проверять систему координат","Считать симуляцию полной заменой проверки на станке"],route:["Чертёж и заготовка","Операции и инструмент","Траектория и симуляция","Постпроцессор и проверка"]},
      "t-3-2": {explanation:"Технологическая документация переводит замысел обработки в однозначные действия. В ней фиксируют операцию, переходы, оборудование, оснастку, инструмент, режимы, базы и контроль. Документы должны быть согласованы между собой и соответствовать принятой на предприятии системе оформления.",caseTitle:"Кейс: оператор получил неполную карту",caseText:"Если в карте нет важного размера, инструмента или условия контроля, не додумывайте его. Сверьте комплект документации и запросите уточнение у ответственного специалиста до выполнения операции.",mistakes:["Использовать устаревшую редакцию документа","Не сверять карту с чертежом","Оставлять режимы и единицы измерения неоднозначными"],route:["Чертёж","Маршрутная карта","Операционная карта","Контроль и запись результата"]},
      "t-3-3": {explanation:"Координатная система станка описывает положение рабочих органов, а система детали задаёт начало отсчёта для конкретной установки. Положение инструмента также связано с его геометрией и корректорами. Ошибка в нуле или знаке координаты смещает всю траекторию.",caseTitle:"Кейс: деталь обработана со смещением",caseText:"Проверьте активную рабочую систему координат, фактическое положение нуля, привязку инструмента и знак координат. Сверьте контрольные точки с чертежом и выполняйте проверку по безопасной процедуре.",mistakes:["Путать машинный ноль и ноль детали","Не учитывать корректор длины/радиуса","Менять знак координаты без проверки направления оси"],route:["Машинная система","База детали","Привязка инструмента","Контроль координат"]},
      "t-3-4": {explanation:"Расчёт контура нужен, чтобы перевести геометрию чертежа в координаты точек и элементов. Для прямых используют конечные точки, для дуг — центр/радиус или поддерживаемый формат задания. Проверяют единицы, знаки, сопряжения и замкнутость контура.",caseTitle:"Задача: контур с уступом и дугой",caseText:"Разбейте профиль на геометрические элементы, назначьте точки перехода, рассчитайте координаты и проверьте совпадение соседних элементов. Сверьте итоговый профиль с размерами чертежа.",mistakes:["Округлять координаты слишком рано","Не проверять касание и сопряжение дуги","Пропускать контроль единиц и знаков"],route:["Разбить профиль","Найти координаты","Проверить сопряжения","Сверить с чертежом"]},
      "t-3-5": {explanation:"Траектория инструмента — путь его контрольной точки с учётом геометрии инструмента и припуска. Важно отличать контур детали от пути центра инструмента. Учитывают подход, отход, безопасные перемещения, компенсацию радиуса и возможные столкновения.",caseTitle:"Кейс: фреза срезает лишнее у стенки",caseText:"Проверьте, задан ли корректный радиус инструмента и компенсация, совпадает ли направление обхода с технологическим заданием, верны ли глубина и припуск. Затем пересчитайте траекторию и повторите симуляцию.",mistakes:["Считать путь центра фрезы контуром детали","Игнорировать подход и отход","Не проверять столкновения держателя и заготовки"],route:["Контур детали","Геометрия инструмента","Компенсация и припуск","Симуляция траектории"]},
      "t-3-6": {explanation:"Кадр УП — строка программы, содержащая адреса и значения. Адреса задают тип данных: координаты, подачу, частоту вращения, номер инструмента и функции. Структура и допустимые сочетания зависят от системы ЧПУ и диалекта программирования.",caseTitle:"Разбор кадра: G01 X40 Z-15 F0.2",caseText:"G01 задаёт рабочее линейное перемещение; X и Z — конечные координаты; F — подача. Перед интерпретацией уточните режим задания координат и единицы, активные на стойке. Это учебный пример, не команда для запуска без контекста.",mistakes:["Считать все G-коды одинаковыми на любой стойке","Не проверять модальные состояния","Путать подачу в мм/мин и мм/об"],route:["Номер кадра","Подготовительные функции","Адреса и значения","Вспомогательные функции"]},
      "t-4-1": {explanation:"Наладка связывает программу, станок, заготовку и инструмент в одну систему. Проверяют исправность оборудования, закрепление, ноль детали, корректоры, инструментальный магазин и режимы. Регулировку выполняют в пределах полномочий и по документации конкретного станка.",caseTitle:"Кейс: после смены инструмента размер ушёл",caseText:"Проверьте правильность позиции инструмента, установку пластины, вылет, геометрический и износный корректор, а также базирование. Изменение корректора должно быть обосновано измерением и разрешённой процедурой.",mistakes:["Исправлять размер без измерения","Путать геометрический и износный корректор","Игнорировать закрепление инструмента"],route:["Подготовить станок","Установить инструмент и заготовку","Задать ноль и корректоры","Проверить наладку"]},
      "t-4-2": {explanation:"Система программного управления получает программу, интерпретирует команды и управляет приводами осей и вспомогательными устройствами. Важно различать программу, устройство ЧПУ, привод, датчики обратной связи и исполнительные механизмы.",caseTitle:"Кейс: ось не достигает заданной точки",caseText:"Не пытайтесь обходить сигнал ограничения. Зафиксируйте сообщение, проверьте режим, разрешённые перемещения и состояние оборудования по руководству; при необходимости вызовите наладчика.",mistakes:["Смешивать ЧПУ и механическую часть станка","Игнорировать аварийные сообщения","Считать датчик обратной связи необязательным"],route:["Программа","Интерпретатор ЧПУ","Привод и датчик","Перемещение оси"]},
      "t-4-3": {explanation:"Разработка УП включает выбор системы координат, инструментов, режимов и последовательности кадров. Программа должна учитывать особенности конкретной стойки, станка, оснастки и технологической документации. Любое изменение требует повторной проверки.",caseTitle:"Кейс: нужно обработать ступенчатый вал",caseText:"Составьте последовательность: безопасный вызов инструмента, запуск шпинделя по принятому режиму, подвод, рабочие проходы, отход, смена инструмента при необходимости и завершение. Координаты и режимы берите только из задания и проверенной технологии.",mistakes:["Копировать программу от другого станка без адаптации","Не задавать безопасные перемещения","Забывать корректное завершение и останов"],route:["Технологический план","Кадры обработки","Проверка режимов","Пробный прогон"]},
      "t-4-4": {explanation:"Современная стойка ЧПУ объединяет экран оператора, режимы работы, редактор программы, коррекции, диагностику, сообщения и управление станком. Конкретное меню зависит от производителя и версии; ориентируйтесь на руководство установленной системы.",caseTitle:"Кейс: на экране появился аварийный код",caseText:"Запишите точный код и текст сообщения, определите момент появления, проверьте руководство и сообщите ответственному специалисту. Не сбрасывайте аварию многократно без выяснения причины.",mistakes:["Нажимать Reset вместо анализа причины","Изменять параметры без допуска","Путать режимы ручного, наладочного и автоматического управления"],route:["Определить режим","Прочитать сообщение","Найти причину по руководству","Выполнить разрешённое действие"]},
      "t-5-1": {explanation:"Сверлильная УП задаёт позиционирование по координатам и цикл обработки отверстий. До программирования определяют координаты отверстий, глубину, инструмент, безопасную высоту и способ удаления стружки. Цикл выбирают по возможностям стойки и материалу.",caseTitle:"Кейс: плита с четырьмя отверстиями",caseText:"Составьте таблицу координат центров отверстий, проверьте расстояния от баз, назначьте сверло и глубину. Определите безопасную плоскость и порядок перехода между отверстиями; сверяйте цикл с руководством стойки.",mistakes:["Забывать безопасную высоту между отверстиями","Не учитывать глубину и выход сверла","Не проверять координаты от выбранной базы"],route:["Схема отверстий","Координаты центров","Инструмент и глубина","Цикл и контроль"]},
      "t-5-2": {explanation:"Токарная программа описывает профиль в координатах, обычно связанных с осями X и Z. При подготовке учитывают диаметр/радиусный режим, ноль детали, инструмент и его коррекцию, направление вращения, подачу, безопасный отвод и цикл обработки.",caseTitle:"Кейс: наружное точение ступенчатого вала",caseText:"По чертежу выделите участки профиля и переходы, назначьте инструмент и точки подхода/отхода. Проверьте, что режим координат и формат подачи соответствуют стойке; смоделируйте обработку и проконтролируйте размеры.",mistakes:["Путать диаметр X с радиусом X","Не учитывать геометрию вершины резца","Не проверять отвод от уступа и патрона"],route:["Профиль детали","Ноль и инструмент","Кадры точения","Проверка и контроль"]},
      "t-5-3": {explanation:"Фрезерная УП описывает перемещение вращающегося инструмента относительно заготовки по осям X, Y и Z. Планируют установку, базирование, плоскости безопасности, стратегию проходов, глубины, припуски и компенсацию инструмента.",caseTitle:"Кейс: обработка кармана",caseText:"Определите границы кармана, глубину, диаметр фрезы, число проходов и способ врезания. Проверьте остаточный материал, траекторию центра инструмента и отсутствие столкновений с прижимами.",mistakes:["Не учитывать прижимы и выступы оснастки","Назначать глубину одним проходом без обоснования","Путать контур кармана и траекторию центра фрезы"],route:["Базирование заготовки","Выбор фрезы","Стратегия и глубина","Симуляция и контроль"]},
      "t-5-4": {explanation:"Аддитивное оборудование формирует изделие последовательным добавлением материала слоями. Подготовка включает модель, ориентацию, поддержку, параметры слоя и процесса, проверку области построения и последующую обработку. Технология зависит от типа оборудования и материала.",caseTitle:"Кейс: печать детали с нависающей стенкой",caseText:"Оцените ориентацию модели, необходимость поддержек, качество поверхности и доступность удаления поддержки. Уточните совместимость материала и режимов с конкретной установкой.",mistakes:["Считать любую 3D-печать одинаковой","Не учитывать усадку и анизотропию","Не предусматривать поддержку и постобработку"],route:["3D-модель","Ориентация и поддержки","Параметры слоёв","Печать и контроль"]}
    },
    "04.01": {
      "m0401-t11": {explanation:"Диагностирование — получение объективной информации о техническом состоянии оборудования. Прямой метод измеряет сам параметр, косвенный оценивает состояние по связанным признакам: вибрации, шуму, температуре, току или изменению точности.",caseTitle:"Кейс: шпиндель стал шуметь сильнее",caseText:"Зафиксируйте режим, при котором возникает шум, сравните его с нормальным состоянием, проверьте доступные диагностические признаки и выберите прибор. Не делайте вывод о неисправности только по одному признаку.",mistakes:["Путать симптом и установленную причину","Сравнивать измерения при разных режимах","Не учитывать погрешность прибора"],route:["Симптом","Выбор параметра","Метод и прибор","Сравнение с нормой"]},
      "m0401-t12": {explanation:"Диагностика типового узла строится по установленной последовательности: подготовка и безопасное отключение, внешний осмотр, проверка креплений и смазки, измерение параметров, сопоставление с нормой и оформление результата. Конкретные допуски берут из паспорта и инструкции.",caseTitle:"Кейс: проверка подшипникового узла",caseText:"Осмотрите корпус и крепления, уточните условия работы, измерьте температуру и вибрацию подходящим прибором, сравните данные с нормативом для данного оборудования. Если требуется разборка или регулировка — выполняйте её только по утверждённой процедуре.",mistakes:["Измерять без фиксации исходного режима","Игнорировать паспортные значения","Переходить к разборке до безопасного отключения"],route:["Подготовка и безопасность","Осмотр узла","Измерения","Оценка и запись"]},
      "m0401-t13": {explanation:"Поиск неисправности — последовательное сужение круга возможных причин. Сначала формулируют симптом и условия его появления, затем проверяют наиболее вероятные и безопасно доступные причины, подтверждают вывод измерениями и документируют результат.",caseTitle:"Кейс: ухудшилось качество поверхности",caseText:"Сопоставьте изменение качества с инструментом, режимами, закреплением, вибрацией, состоянием направляющих и материалом заготовки. Проверяйте причины по одной, фиксируя результаты, а не меняйте сразу несколько параметров.",mistakes:["Менять сразу несколько настроек","Объявлять причину без проверки","Не записывать условия появления дефекта"],route:["Симптом и условия","Гипотезы причин","Проверка по очереди","Подтверждение и запись"]},
      "m0401-t14": {explanation:"Наладка металлорежущего станка — подготовка оборудования к выполнению заданной операции. Она включает проверку технического состояния, установку оснастки и инструмента, базирование заготовки, выбор режимов и пробную проверку. Порядок зависит от модели станка и инструкции.",caseTitle:"Кейс: подготовка станка к новой операции",caseText:"Сверьте задание и паспорт станка, проверьте крепления, установите подходящую оснастку и инструмент, выполните базирование и контрольные проверки. Не запускайте станок при неисправных ограждениях или неясных настройках.",mistakes:["Начинать наладку без технологического задания","Не проверять надёжность закрепления","Пропускать пробный контроль"],route:["Задание и паспорт","Осмотр оборудования","Установка и настройка","Пробная проверка"]},
      "m0401-t15": {explanation:"Способ наладки зависит от кинематики и назначения станка. Для токарного важны соосность, патрон, резцедержатель и оси; для фрезерного — базирование, стол, приспособление, инструмент и плоскости; для сверлильного — положение отверстий, вылет и перпендикулярность.",caseTitle:"Кейс: одна деталь — разные станки",caseText:"Сравните, какие базы и приспособления потребуются для токарной, фрезерной и сверлильной операции. Объясните, какие параметры проверяются перед пуском и почему нельзя переносить настройку одного станка на другой без адаптации.",mistakes:["Использовать одинаковый чек-лист без учёта конструкции","Не проверять соосность или перпендикулярность","Игнорировать ограничения оснастки"],route:["Определить тип станка","Выбрать базы и оснастку","Выполнить настройку","Проверить геометрию"]},
      "m0401-t16": {explanation:"Ремонт восстанавливает работоспособность оборудования, а TPM направлена на предупреждение потерь и поддержание надёжности совместными действиями персонала. Оператор выполняет разрешённый уход и осмотр, фиксирует отклонения, но не заменяет ремонтный персонал.",caseTitle:"Кейс: повторяющиеся остановки из-за загрязнения",caseText:"Проанализируйте журнал остановок, выделите повторяющийся фактор, предложите безопасные ежедневные действия по поддержанию чистоты и смазки в пределах инструкции и критерии эскалации неисправности.",mistakes:["Смешивать обслуживание и ремонт","Скрывать повторяющиеся мелкие отказы","Выполнять ремонт без допуска и отключения энергии"],route:["Осмотр и профилактика","Раннее выявление отклонений","Планирование обслуживания","Анализ повторных отказов"]}
    }
  };
})();